import{_ as o,o as e,c as a,ai as r}from"./chunks/framework.BBSijY9B.js";const h=JSON.parse('{"title":"Bot 不回复了？按这个顺序排查，别一上来就重置","description":"","frontmatter":{"date":"2026-10-20T00:00:00.000Z","title":"Bot 不回复了？按这个顺序排查，别一上来就重置","summary":"先看官方状态页，再重发、重开、更新、恢复，「重置」永远放最后。附一段可以直接发给 Bot 的自查提示词。","category":"使用技巧","tags":["故障排查","云电脑","用量"],"sources":[{"url":"https://cursor.com/help/grok-bot/faqs","author":"Grok Bot FAQs","platform":"官方帮助中心"}],"updates":[{"link":"/faq/faq","title":"常见问题"}],"wordCount":511,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Bot 不回复了？按这个顺序排查，别一上来就重置 | WANGXXXL"}],["meta",{"property":"og:description","content":"先看官方状态页，再重发、重开、更新、恢复，「重置」永远放最后。附一段可以直接发给 Bot 的自查提示词。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/daily/2026-10-20-bot-not-replying"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/daily-2026-10-20-bot-not-replying-c0f8b0a244.png"}],["meta",{"property":"og:image:alt","content":"Bot 不回复了？按这个顺序排查，别一上来就重置 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"Bot 不回复了？按这个顺序排查，别一上来就重置 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"先看官方状态页，再重发、重开、更新、恢复，「重置」永远放最后。附一段可以直接发给 Bot 的自查提示词。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/daily-2026-10-20-bot-not-replying-c0f8b0a244.png"}],["meta",{"name":"twitter:image:alt","content":"Bot 不回复了？按这个顺序排查，别一上来就重置 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/daily/2026-10-20-bot-not-replying"}]]},"headers":[],"relativePath":"daily/2026-10-20-bot-not-replying.md","filePath":"daily/2026-10-20-bot-not-replying.md","lastUpdated":1792499451000}'),n={name:"daily/2026-10-20-bot-not-replying.md"};function i(l,t,s,d,p,c){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="bot-不回复了-按这个顺序排查-别一上来就重置" tabindex="-1">Bot 不回复了？按这个顺序排查，别一上来就重置 <a class="header-anchor" href="#bot-不回复了-按这个顺序排查-别一上来就重置" aria-label="Permalink to &quot;Bot 不回复了？按这个顺序排查，别一上来就重置&quot;">​</a></h1><p>很多人遇到 Bot 不回复，第一反应是&quot;重置电脑&quot;。这恰恰是最不该先做的：<strong>重置可能丢掉最近还没保存的改动</strong>，而且如果问题出在服务端，重置根本没用。</p><h2 id="先分清是哪一类" tabindex="-1">先分清是哪一类 <a class="header-anchor" href="#先分清是哪一类" aria-label="Permalink to &quot;先分清是哪一类&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你看到的</th><th>多半是</th><th>怎么办</th></tr></thead><tbody><tr><td>提示用量用完</td><td>本周用量用光了，不是坏了</td><td>用量每周重置；急用就按官方渠道增加额度</td></tr><tr><td>Bot failed to respond / Model provider is overloaded</td><td>临时故障</td><td>等一会儿重发</td></tr><tr><td>一直 Reconnecting / Couldn&#39;t Reach Grok Bot&#39;s Computer</td><td>云电脑连不上</td><td>按下面的顺序来</td></tr><tr><td>聊天或 Bot 不见了</td><td>多半没被删</td><td>见文末</td></tr></tbody></table><h2 id="排查顺序-从轻到重" tabindex="-1">排查顺序（从轻到重） <a class="header-anchor" href="#排查顺序-从轻到重" aria-label="Permalink to &quot;排查顺序（从轻到重）&quot;">​</a></h2><div class="steps"><ol><li><strong>看状态页</strong>：打开 <a href="https://status.cursor.com" target="_blank" rel="noopener noreferrer">status.cursor.com</a>，看 Grok Bot 那一行。应用里不显示服务状态，状态页是唯一准的地方。有故障就等它恢复，<strong>这时不要重置、不要重装</strong>。</li><li><strong>重发一次</strong>：状态页正常、只是报错，等一会儿再发。</li><li><strong>完全退出再打开</strong>：不是关窗口，是彻底退出应用。</li><li><strong>更新</strong>：在设置里检查更新，也更新一下 Bot 的电脑。</li><li><strong>恢复（Recover）</strong>：界面提供的恢复选项。</li><li><strong>重置（Reset）</strong>：最后一步。和恢复一样，云电脑连不上时可能丢失最近的改动。</li></ol></div><h2 id="卡在-一直在工作-但没进展" tabindex="-1">卡在&quot;一直在工作&quot;但没进展 <a class="header-anchor" href="#卡在-一直在工作-但没进展" aria-label="Permalink to &quot;卡在&quot;一直在工作&quot;但没进展&quot;">​</a></h2><p>先打开电脑预览，看它停在哪一步。最常见的是登录页、验证码或弹窗。直接问它：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你现在卡在哪一步？截图给我看，并说明需要我做什么。</span></span></code></pre></div><h2 id="聊天或-bot-不见了" tabindex="-1">聊天或 Bot &quot;不见了&quot; <a class="header-anchor" href="#聊天或-bot-不见了" aria-label="Permalink to &quot;聊天或 Bot &quot;不见了&quot;&quot;">​</a></h2><p>通常没有被删除。依次检查：完全退出重开 → 换一台设备看看 → 侧边栏底部的 <strong>Hidden Bots</strong>（隐藏的 Bot）→ 确认登录的是同一个账号。<strong>不要用恢复或重置去找</strong>，那不会把它们变回来。</p><h2 id="还不行就联系支持" tabindex="-1">还不行就联系支持 <a class="header-anchor" href="#还不行就联系支持" aria-label="Permalink to &quot;还不行就联系支持&quot;">​</a></h2><p>附上账号邮箱、版本信息（账户菜单 → Support → About → Copy version info）、截图和请求 ID（右键消息 → Copy request ID）。</p>',13)])])}const m=o(n,[["render",i]]);export{h as __pageData,m as default};
